package br.com.minhagibiteca.catalog.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="works") public class Work { @Id private UUID id; @Column(name="owner_user_id",nullable=false) private UUID ownerUserId; @Column(nullable=false) private String title; @Column(name="normalized_title",nullable=false) private String normalizedTitle; @Column(name="original_year") private Integer originalYear; private String summary; @Column(name="created_at") private Instant createdAt; protected Work(){} public static Work create(UUID owner,String title){Work w=new Work();w.id=UUID.randomUUID();w.ownerUserId=owner;w.title=title.trim();w.normalizedTitle=w.title.toLowerCase(Locale.ROOT);w.createdAt=Instant.now();return w;} public UUID getId(){return id;} public UUID getOwnerUserId(){return ownerUserId;} public String getTitle(){return title;} }
